export function Appointment({
  title = "{{title}}",
  date = "{{date}}",
  time = "{{time}}",
  status = "{{status}}",
  accent = "{{accent}}",
}) {
  const statusColor = { Confirmed: ["#A8E6C1", "#14351f"], Tentative: ["#E8A020", "#241430"], Cancelled: ["#D64545", "#FAF7F2"] }[status] ?? ["#A8E6C1", "#14351f"];
  return (
    <article style={{ font: "15px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 360, padding: "18px 20px", borderRadius: 12, borderLeft: `4px solid ${accent}`, boxSizing: "border-box", boxShadow: "0 6px 18px rgba(36,20,48,.10)" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
        <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>{title}</h3>
        <span style={{ fontSize: 12, fontWeight: 700, padding: "4px 10px", borderRadius: 999, background: statusColor[0], color: statusColor[1] }}>{status}</span>
      </div>
      <p style={{ margin: "10px 0 0", fontSize: 14, color: "#24143099" }}>
        <time dateTime={date}>{date}</time> &middot; {time}
      </p>
    </article>
  );
}
